/* MEASURE-7, RU-56 candidate b: hover 12 %, current 26 %, press 34 % of the dock's ink over the plate, on .glass-dock */
.glass-dock {
    --dock-control-hover-bg: color-mix(in oklab, var(--dock-fg-on-aurora) 12%, transparent);
    --dock-control-active-bg: color-mix(in oklab, var(--dock-fg-on-aurora) 26%, transparent);
    --dock-control-press-bg: color-mix(in oklab, var(--dock-fg-on-aurora) 34%, transparent);
    --glass-capsule-fill: color-mix(in oklab, var(--dock-fg-on-aurora) 26%, transparent);
}
